const $=id=>document.getElementById(id);
export function expansionUI({send,storage,look,toast}){let profile,grenade='he',flashUntil=0,killUntil=0;let token=storage.get('s16.profileId','');if(!token){token=crypto.randomUUID();storage.set('s16.profileId',token)}
 const card=document.createElement('section');card.id='profileCard';card.innerHTML='<label>Kaplama<select id="skinSelect"><option value="standard">Standart</option></select></label>';$('nickname').closest('.callsign').after(card);
 const util=document.createElement('div');util.id='utilityBar';util.innerHTML='<button data-util="he">G · EL BOMBASI</button><button data-util="flash">H · FLAŞ</button><button data-util="smoke">J · SİS</button>';$('hud').append(util);for(const b of util.children)b.onclick=()=>{grenade=b.dataset.util;paintUtil()};
 const flash=document.createElement('div');flash.id='flashEffect';document.body.append(flash);const kill=document.createElement('div');kill.id='killcam';kill.hidden=true;document.body.append(kill);
 const advanced=document.createElement('fieldset');advanced.innerHTML='<legend>Mobil ve performans</legend><label>Hedef FPS<select id="targetFps"><option>30</option><option selected>60</option><option>90</option></select></label><label class="checkbox"><input id="gyroToggle" type="checkbox"> Jiroskopla nişan</label><button id="gyroPermission" type="button" class="outline">JİROSKOBU ETKİNLEŞTİR</button>';$('settingsDialog').insertBefore(advanced,$('settingsDialog').lastElementChild);
 let gyro=storage.get('s16.gyro','false')==='true',base=null;$('gyroToggle').checked=gyro;$('gyroToggle').onchange=()=>{gyro=$('gyroToggle').checked;storage.set('s16.gyro',String(gyro));base=null};$('targetFps').value=storage.get('s16.targetFps','60');$('targetFps').onchange=()=>storage.set('s16.targetFps',$('targetFps').value);$('gyroPermission').onclick=async()=>{try{if(typeof DeviceOrientationEvent?.requestPermission==='function'&&(await DeviceOrientationEvent.requestPermission())!=='granted')throw Error();gyro=true;$('gyroToggle').checked=true;storage.set('s16.gyro','true');toast('Jiroskop etkin.')}catch{toast('Jiroskop izni verilemedi.')}};addEventListener('deviceorientation',e=>{if(!gyro||e.gamma==null||e.beta==null)return;if(!base){base={g:e.gamma,b:e.beta};return}look((e.gamma-base.g)*.16,(e.beta-base.b)*.12);base={g:e.gamma,b:e.beta}});
 function paintUtil(){for(const b of util.children)b.classList.toggle('selected',b.dataset.util===grenade)}function paintProfile(){if(!profile)return;$('skinSelect').replaceChildren(...profile.skins.map(s=>Object.assign(document.createElement('option'),{value:s.id,textContent:s.label,disabled:!s.unlocked})));$('skinSelect').value=profile.skin}$('skinSelect').onchange=()=>send({type:'skin',skin:$('skinSelect').value});paintUtil();
 return{hello(){send({type:'identify',profileId:token})},grenade:()=>grenade,targetFps:()=>Number($('targetFps').value)||60,message(m){if(m.type==='profile'){profile=m.profile;paintProfile();return true}if(m.type==='flash'){flashUntil=performance.now()+Math.max(300,m.duration||1800);return true}if(m.type==='mapvote')return true;return false},kill(m,myId){if(m.victimId!==myId)return;kill.textContent='ÖLDÜRME KAMERASI · '+m.killer+' · '+String(m.weapon||'').toUpperCase();kill.hidden=false;killUntil=performance.now()+2500},state(s,own){document.body.classList.toggle('inside-smoke',(s.smokes||[]).some(x=>Math.hypot((own?.x||0)-x.x,(own?.z||0)-x.z)<4))},update(now){flash.style.opacity=now<flashUntil?String(Math.min(1,(flashUntil-now)/500)):0;if(now>killUntil)kill.hidden=true}}}
